package io.scenariomesh.workerruntime; import io.scenariomesh.core.*;import io.scenariomesh.core.Domain.*;import java.time.*;
public final class LocalWorkerLauncher implements Ports.WorkerLauncher {public Ports.WorkerHandle launch(Ports.WorkerLaunchRequest r)throws Exception{var pb=new ProcessBuilder(r.command());pb.directory(r.workingDirectory().toFile());pb.redirectErrorStream(true);var p=pb.start();return new Handle(r.id(),p);}private record Handle(WorkerId id,Process p)implements Ports.WorkerHandle{public boolean alive(){return p.isAlive();}public void stop(Duration timeout)throws Exception{p.destroy();if(!p.waitFor(timeout.toMillis(),java.util.concurrent.TimeUnit.MILLISECONDS)){p.destroyForcibly();p.waitFor();}}}}
